    ldp   x5, x6, [x1, #16]
    ldr   x7, [x1, #32]
    adds  x8, x3, x3
    adcs  x9, x4, x4
    adcs  x10, x5, x5
    adcs  x11, x6, x6
    adc   x12, x7, x7
    stp   x8, x9, [sp, #40]
    stp   x10, x11, [sp, #56]
    str   x12, [sp, #72]
    // s = a0 + a1 (unreduced) -> [sp]
    ldp   x8, x9, [x1, #40]
    ldp   x10, x11, [x1, #56]
    ldr   x12, [x1, #72]
    adds  x8, x8, x3
    adcs  x9, x9, x4
    adcs  x10, x10, x5
    adcs  x11, x11, x6
    adc   x12, x12, x7
    stp   x8, x9, [sp]
    stp   x10, x11, [sp, #16]
    str   x12, [sp, #32]
    // d = a0 - a1 + p (unreduced, in (0, 2p)) -> x3..x7
    ldp   x8, x9, [x1, #40]
    subs  x3, x3, x8
    sbcs  x4, x4, x9
    ldp   x8, x9, [x1, #56]
    sbcs  x5, x5, x8
    sbcs  x6, x6, x9
    ldr   x8, [x1, #72]
    sbcs  x7, x7, x8
    mov   x8, #-1
    movn  x9, #0xd870, lsl #48       // p[4] = 0x278FFFFFFFFFFFFF
    adds  x3, x3, x8
    adcs  x4, x4, x8
    adcs  x5, x5, x8
    adcs  x6, x6, x8
    adc   x7, x7, x9

    // c0 = d x s -> [out] (a0's slot; a1 is still intact if c == a)
    // x8..x13 <- z = a x b0
    ldr   x14, [sp]
    MUL64x320  x8,x9,x10,x11,x12,x13, x3,x4,x5,x6,x7, x14, x15
    FPMUL320x320  sp, x3,x4,x5,x6,x7, x8,x9,x10,x11,x12,x13, x14, x15
    // reduce x13,x8..x11 into [0, p)
    mov   x14, #-1
    movn  x15, #0xd870, lsl #48      // p[4] = 0x278FFFFFFFFFFFFF
    subs  x13, x13, x14
    sbcs  x8, x8, x14
    sbcs  x9, x9, x14
    sbcs  x10, x10, x14
    sbcs  x11, x11, x15
    sbc   x14, xzr, xzr              // mask = -borrow
    and   x15, x15, x14
    adds  x13, x13, x14
    adcs  x8, x8, x14
    adcs  x9, x9, x14
    adcs  x10, x10, x14
    adc   x11, x11, x15
    stp   x13, x8, [x0]
    stp   x9, x10, [x0, #16]
    str   x11, [x0, #32]

    // c1 = a1 x t -> [out+40]
    ldp   x3, x4, [x1, #40]
    ldp   x5, x6, [x1, #56]
    ldr   x7, [x1, #72]
    add   x1, sp, #40                // x1 is dead after the a1 load: reuse it as the t pointer
    // x13,x8..x12 <- z = a x b0
    ldr   x14, [x1]
    MUL64x320  x13,x8,x9,x10,x11,x12, x3,x4,x5,x6,x7, x14, x15
    FPMUL320x320  x1, x3,x4,x5,x6,x7, x13,x8,x9,x10,x11,x12, x14, x15
    // reduce x12,x13,x8..x10 into [0, p)
    mov   x14, #-1
    movn  x15, #0xd870, lsl #48      // p[4] = 0x278FFFFFFFFFFFFF
    subs  x12, x12, x14
    sbcs  x13, x13, x14
